update public.ea_records set data=jsonb_set(data,'{coverageNote}',to_jsonb('Democratic-era national elections, 1983–2025: Chamber of Deputies renewals, indirect and direct Senate elections, presidential ballots and parliamentary presidential selections. Earlier elections are outside this series. Historical party categories may combine allied lists; those tables are marked partial. The 2025 national vote compilation is marked provisional. Seats count each renewal, with comparisons to the same outgoing cohort where labels remain comparable.'::text)),updated=now() where kind='world_country' and data->>'id'='ar' and data->>'coverageNote'='Selected records only. Earlier elections and additional result detail are still being added.';
