insert into public.ea_records(id,kind,data,updated) values('world-argentina-presidential-parliamentary-2001','world_election','{"id":"world-argentina-presidential-parliamentary-2001","countryId":"ar","title":"Argentina parliamentary presidential election 2001","type":"presidential","body":"President of Argentina","startDate":"2001-12-23","endDate":"","precision":"day","dateStatus":"confirmed","status":"held","publication":"published","round":"","seriesId":"argentina-president","snap":true,"summary":"Congress selected Adolfo Rodríguez Saá as President of Argentina following the presidential succession crisis.","government":"","turnout":null,"totalSeats":null,"resultStatus":"final","resultCoverage":"complete","voteBasis":"Affirmative Legislative Assembly votes as a share of votes for or against the appointment","results":[{"id":"adolfo-rodriguez-saa","name":"Adolfo Rodríguez Saá","party":"Justicialist Party","color":"#318CE7","votes":169,"share":55.05,"seats":null,"previousSeats":null,"electoralVotes":null,"winner":true,"ideologyIds":[],"partyId":"b669fbee-691e-5265-81b7-8507204e2ec5","ideologyBasis":{"kind":"party-era","year":2001,"note":"Peronism / Justicialism. The party has contained left- and right-wing tendencies; a single economic ideology is not assigned across these eras.","sources":[{"label":"Party history and political tradition","url":"https://en.wikipedia.org/wiki/Justicialist_Party"}]}}],"sources":[{"label":"Official parliamentary appointment decree","url":"https://www.argentina.gob.ar/normativa/nacional/decreto-989-2001-71061/texto"},{"label":"Contemporary selection and vote count","url":"https://www.cidob.org/lider-politico/adolfo-rodriguez-saa"}],"checked":"2026-10-14","notes":"This is an indirect congressional selection. The assembly recorded 169 votes for and 138 against the appointment. The percentage excludes abstentions. Opposition votes are not assigned to an invented rival candidate. Public turnout is not applicable.","articleId":"","version":1,"electionMethod":"indirect","linkedElectionIds":["world-argentina-deputies-2001","world-argentina-senate-2001"]}'::jsonb,now()) on conflict(id) do nothing;
